# Fetch all liked songs, albums, and playlists to collect all song IDs
access_token = spotify_login['access_token']

# Liked songs
liked_song_ids = set()
page_index = 0
while True:
    page = apis.spotify.show_liked_songs(access_token=access_token, page_index=page_index, page_limit=20)
    if not page:
        break
    for song in page:
        liked_song_ids.add(song['song_id'])
    if len(page) < 20:
        break
    page_index += 1

# Liked albums
album_song_ids = set()
page_index = 0
while True:
    page = apis.spotify.show_liked_albums(access_token=access_token, page_index=page_index, page_limit=20)
    if not page:
        break
    for album in page:
        for sid in album.get('song_ids', []):
            album_song_ids.add(sid)
    if len(page) < 20:
        break
    page_index += 1

# Liked playlists
playlist_song_ids = set()
page_index = 0
while True:
    page = apis.spotify.show_liked_playlists(access_token=access_token, page_index=page_index, page_limit=20)
    if not page:
        break
    for pl in page:
        for sid in pl.get('song_ids', []):
            playlist_song_ids.add(sid)
    if len(page) < 20:
        break
    page_index += 1

all_song_ids = liked_song_ids | album_song_ids | playlist_song_ids
print(f"Liked songs: {len(liked_song_ids)}, Album songs: {len(album_song_ids)}, Playlist songs: {len(playlist_song_ids)}, Total unique: {len(all_song_ids)}")
print(sorted(all_song_ids))

