  {
   "name": "phone_number",
   "type": "string",
   "required": true,
   "description": "The phone number of the contact to send the message to.",
   "default": null,
   "constraints": []
  },
  {
   "name": "message",
   "type": "string",
   "required": true,
   "description": "The content of the text message.",
   "default": null,
   "constraints": [
    "length >= 1"
   ]
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from phone app login.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string",
   "text_message_id": 1
  },
  "failure": {
   "message": "string"
  }
 }
}
